#include <iostream>
#include <cstdlib>
using namespace std;

class MemoryPool {
    char* buffer;
    size_t blockSize, totalBlocks;
    bool* freeList;
public:
    MemoryPool(size_t blockSz, size_t numBlocks) : blockSize(blockSz), totalBlocks(numBlocks) {
        buffer = new char[blockSize * numBlocks];
        freeList = new bool[numBlocks]();
        for (size_t i = 0; i < numBlocks; i++) freeList[i] = true;
    }

    void* allocate() {
        for (size_t i = 0; i < totalBlocks; i++) {
            if (freeList[i]) {
                freeList[i] = false;
                cout << "Allocated block " << i << endl;
                return buffer + i * blockSize;
            }
        }
        cout << "No free blocks!" << endl;
        return nullptr;
    }

    void deallocate(void* ptr) {
        if (!ptr) return;
        size_t index = ((char*)ptr - buffer) / blockSize;
        freeList[index] = true;
        cout << "Freed block " << index << endl;
    }

    ~MemoryPool() { delete[] buffer; delete[] freeList; }
};

int main() {
    MemoryPool pool(64, 5);
    int* a = (int*)pool.allocate();
    int* b = (int*)pool.allocate();
    a[0] = 42; b[0] = 99;
    cout << "a[0]=" << a[0] << " b[0]=" << b[0] << endl;
    pool.deallocate(a);
    pool.deallocate(b);
    return 0;
}
